<script setup lang="ts">
import type { LocalName } from '../types/localGraph'
const names=defineModel<LocalName[]>({required:true})
const preferred=defineModel<string|null>('preferred',{default:null})
function add(){names.value=[...names.value,{id:crypto.randomUUID(),text:'',locale:'und',kind:'ALIAS',source:'LOCAL',reviewStatus:'MANUAL'}]}
function remove(id:string){names.value=names.value.filter(n=>n.id!==id);if(preferred.value===id)preferred.value=null}
</script>
<template><fieldset class="name-editor"><legend>多语言名称</legend><p>至少填写一种。默认优先中文，再按有依据的原语言与来源主名；未知语言请选择 und，可自由填写语言标记。</p><div v-for="(name,index) in names" :key="name.id" class="name-row"><label>名称 {{ index+1 }}<input v-model="name.text" required maxlength="200"></label><label>语言<input v-model="name.locale" required list="name-locales" placeholder="zh / ja / en / und" maxlength="35"></label><label>类型<select v-model="name.kind"><option value="PRIMARY">主名</option><option value="ORIGINAL">原名</option><option value="ALIAS">别名</option></select></label><button type="button" :disabled="names.length===1" @click="remove(name.id)">移除</button></div><datalist id="name-locales"><option value="zh">中文</option><option value="zh-Hans">简体中文</option><option value="zh-Hant">繁体中文</option><option value="ja">日文</option><option value="en">英文</option><option value="ko">韩文</option><option value="und">未知语言</option></datalist><button type="button" :disabled="names.length>=30" @click="add">添加名称</button><label>显示名称<select v-model="preferred"><option :value="null">按语言优先级自动选择</option><option v-for="name in names" :key="name.id" :value="name.id">{{ name.text || '尚未填写' }}（{{ name.locale }}）</option></select></label></fieldset></template>
<style scoped>.name-editor{margin:0;padding:16px;border:1px solid #d5e0d8;border-radius:8px}.name-editor p{font-size:12px;line-height:1.8}.name-row{display:grid;grid-template-columns:minmax(100px,2fr) minmax(70px,1fr) 85px auto;gap:10px;align-items:end;margin:12px 0}.name-editor label{font-size:12px;display:grid;gap:7px}.name-editor>label{margin-top:14px}.name-row button{padding:8px;font-size:11px}@media(max-width:560px){.name-row{grid-template-columns:1fr 1fr}.name-row>label:first-child{grid-column:1/-1}}</style>
